-- Additive platform migration. Existing account and quotation tables are preserved.
CREATE TABLE IF NOT EXISTS idea_schema_versions (version VARCHAR(80) PRIMARY KEY, applied_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_user_security (user_id CHAR(32) PRIMARY KEY, email_verified_at BIGINT NULL, deletion_requested_at BIGINT NULL, notification_preferences TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_email_tokens (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(32) NOT NULL, purpose VARCHAR(24) NOT NULL, expires_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_addresses (id CHAR(32) PRIMARY KEY, user_id CHAR(32) NOT NULL, label VARCHAR(80) NOT NULL, recipient VARCHAR(160) NOT NULL, phone VARCHAR(40) NOT NULL, governorate VARCHAR(100) NOT NULL, city VARCHAR(120) NOT NULL, street VARCHAR(400) NOT NULL, building VARCHAR(80) NOT NULL, floor_number VARCHAR(40) NOT NULL, apartment VARCHAR(40) NOT NULL, postal_code VARCHAR(20) NOT NULL, instructions VARCHAR(1000) NOT NULL, created_at BIGINT NOT NULL, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_company_verification (company_id CHAR(32) PRIMARY KEY, state VARCHAR(32) NOT NULL, review_notes TEXT NOT NULL, updated_at BIGINT NOT NULL, FOREIGN KEY(company_id) REFERENCES idea_companies(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_company_documents (id CHAR(32) PRIMARY KEY, company_id CHAR(32) NOT NULL, kind VARCHAR(60) NOT NULL, original_name VARCHAR(200) NOT NULL, mime VARCHAR(80) NOT NULL, bytes INT NOT NULL, sha256 CHAR(64) NOT NULL, storage_key CHAR(64) NOT NULL, scan_status VARCHAR(32) NOT NULL, created_at BIGINT NOT NULL, INDEX(company_id), FOREIGN KEY(company_id) REFERENCES idea_companies(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_notifications (id CHAR(32) PRIMARY KEY, user_id CHAR(32) NOT NULL, event_key VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, link VARCHAR(500) NOT NULL, read_at BIGINT NULL, created_at BIGINT NOT NULL, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_mail_outbox (id CHAR(32) PRIMARY KEY, user_id CHAR(32) NULL, event_key VARCHAR(190) NOT NULL UNIQUE, recipient VARCHAR(190) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(24) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_attempt_at BIGINT NOT NULL, last_error VARCHAR(500) NOT NULL DEFAULT '', sent_at BIGINT NULL, created_at BIGINT NOT NULL, INDEX(status,next_attempt_at), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_commerce_variants (id CHAR(32) PRIMARY KEY, product_id VARCHAR(100) NOT NULL, company_id CHAR(32) NULL, sku VARCHAR(100) NOT NULL UNIQUE, label VARCHAR(200) NOT NULL, unit VARCHAR(16) NOT NULL, price_cents BIGINT NOT NULL, stock_milli BIGINT NOT NULL, reserved_milli BIGINT NOT NULL DEFAULT 0, tax_basis_points INT NOT NULL DEFAULT 0, authorized TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 0, evidence VARCHAR(1000) NOT NULL, updated_at BIGINT NOT NULL, INDEX(product_id), FOREIGN KEY(company_id) REFERENCES idea_companies(id) ON DELETE RESTRICT, CHECK(price_cents>0), CHECK(stock_milli>=0), CHECK(reserved_milli>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_cart_items (user_id CHAR(32) NOT NULL, variant_id CHAR(32) NOT NULL, quantity_milli BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,variant_id), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE, FOREIGN KEY(variant_id) REFERENCES idea_commerce_variants(id) ON DELETE CASCADE, CHECK(quantity_milli>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_shipping_methods (id CHAR(32) PRIMARY KEY, name VARCHAR(160) NOT NULL, governorate VARCHAR(100) NOT NULL, price_cents BIGINT NOT NULL, provider VARCHAR(24) NOT NULL, active TINYINT NOT NULL DEFAULT 0, details TEXT NOT NULL, CHECK(price_cents>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_orders (id CHAR(32) PRIMARY KEY, user_id CHAR(32) NOT NULL, idempotency_key VARCHAR(100) NOT NULL, status VARCHAR(32) NOT NULL, payment_status VARCHAR(24) NOT NULL, payment_method VARCHAR(32) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EGP', subtotal_cents BIGINT NOT NULL, tax_cents BIGINT NOT NULL, shipping_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, address_snapshot TEXT NOT NULL, shipping_method_id CHAR(32) NOT NULL, reservation_expires_at BIGINT NULL, cancellation_requested_at BIGINT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE(user_id,idempotency_key), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE RESTRICT, FOREIGN KEY(shipping_method_id) REFERENCES idea_shipping_methods(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_order_items (id CHAR(32) PRIMARY KEY, order_id CHAR(32) NOT NULL, variant_id CHAR(32) NOT NULL, company_id CHAR(32) NULL, product_snapshot TEXT NOT NULL, quantity_milli BIGINT NOT NULL, unit_price_cents BIGINT NOT NULL, subtotal_cents BIGINT NOT NULL, tax_cents BIGINT NOT NULL, FOREIGN KEY(order_id) REFERENCES idea_orders(id) ON DELETE CASCADE, FOREIGN KEY(variant_id) REFERENCES idea_commerce_variants(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_payments (id CHAR(32) PRIMARY KEY, order_id CHAR(32) NOT NULL, provider VARCHAR(24) NOT NULL, provider_order_id VARCHAR(100) NULL UNIQUE, provider_intention_id VARCHAR(100) NULL, provider_transaction_id VARCHAR(100) NULL UNIQUE, status VARCHAR(24) NOT NULL, amount_cents BIGINT NOT NULL, currency CHAR(3) NOT NULL, checkout_url TEXT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, FOREIGN KEY(order_id) REFERENCES idea_orders(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_payment_events (event_key VARCHAR(190) PRIMARY KEY, payment_id CHAR(32) NOT NULL, kind VARCHAR(40) NOT NULL, payload_hash CHAR(64) NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(payment_id) REFERENCES idea_payments(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_refunds (id CHAR(32) PRIMARY KEY, order_id CHAR(32) NOT NULL, payment_id CHAR(32) NOT NULL, amount_cents BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(24) NOT NULL, provider_reference VARCHAR(120) NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, FOREIGN KEY(order_id) REFERENCES idea_orders(id) ON DELETE RESTRICT, FOREIGN KEY(payment_id) REFERENCES idea_payments(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_deliveries (id CHAR(32) PRIMARY KEY, order_id CHAR(32) NOT NULL UNIQUE, provider VARCHAR(24) NOT NULL, provider_id VARCHAR(120) NULL UNIQUE, tracking_number VARCHAR(120) NULL, status VARCHAR(40) NOT NULL, history TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, FOREIGN KEY(order_id) REFERENCES idea_orders(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_invoices (id CHAR(32) PRIMARY KEY, order_id CHAR(32) NOT NULL UNIQUE, invoice_number VARCHAR(80) NOT NULL UNIQUE, status VARCHAR(24) NOT NULL, snapshot TEXT NOT NULL, issued_at BIGINT NOT NULL, FOREIGN KEY(order_id) REFERENCES idea_orders(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_ai_jobs (id CHAR(32) PRIMARY KEY, user_id CHAR(32) NOT NULL, parent_id CHAR(32) NULL, product_id VARCHAR(100) NOT NULL, state VARCHAR(24) NOT NULL, settings TEXT NOT NULL, error_code VARCHAR(100) NOT NULL DEFAULT '', attempts INT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, INDEX(user_id,created_at), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_platform_settings (setting_key VARCHAR(100) PRIMARY KEY, value_json TEXT NOT NULL, updated_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idea_product_comparisons (user_id CHAR(32) NOT NULL, product_id VARCHAR(100) NOT NULL, PRIMARY KEY(user_id,product_id), FOREIGN KEY(user_id) REFERENCES idea_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
